# Son kontrol: kopyalar.txt var mı ve içeriği doğru mu?
import os

if os.path.exists("kopyalar.txt"):
    with open("kopyalar.txt", "r", encoding="utf-8") as f:
        lines = f.readlines()

    print(f"kopyalar.txt dosyası mevcut: {len(lines)} satır")
    for i, line in enumerate(lines, 1):
        print(f"{i}: {line.rstrip()}")

    # Her satırda " | " ayırıcısı ve en az 2 yol var mı?
    valid = True
    for line in lines:
        parts = line.strip().split(" | ")
        if len(parts) < 2:
            print(f"UYARI: {line.strip()} '{ | }' ayrıcısından 2'den az parça içeriyor!")
            valid = False

    if valid:
        print("\n✓ Tüm satırlar geçerli: her satır en az 2 dosya yollarını ' | ' ile ayırıyor.")
else:
    print("kopyalar.txt dosyası bulunamadı!")

